package dev.baranhan.viltrumitecore.client.thor;

import java.util.List;
import net.minecraft.resources.ResourceLocation;

/**
 * Thor rework R1: art paths and the stable bone / locator names of Thor's own body
 * (generated by tools/assets/make_thor_body.py; skeleton reference in
 * docs/design/2026-10-28-thor-rework.md §1.1). R2 clips animate these names only.
 * The body is drawn at scale 1 (1 px = 1/16 block, ~51 px = 3.2 blocks), not at the vanilla 0.9375.
 */
public final class ThorAssets {
   public static final ResourceLocation BODY = loc("geo/thor/thor.geo.json");
   public static final ResourceLocation ARMS = loc("geo/thor/thor_arms.geo.json");
   public static final ResourceLocation TEXTURE = loc("textures/entity/thor/thor_body.png");
   public static final ResourceLocation ANIMATIONS = loc("animations/thor/thor.animation.json");
   /** The unchanged Mjölnir models (tools/assets/convert_thor.py); drawn by their {@link #MJOLNIR_BONE} subtree. */
   public static final ResourceLocation MJOLNIR_HAND = loc("geo/thor/mjolnir_hand.geo.json");
   public static final ResourceLocation MJOLNIR_BELT = loc("geo/thor/mjolnir_belt.geo.json");
   public static final ResourceLocation MJOLNIR_TEXTURE = loc("textures/entity/thor/mjolnir.png");
   public static final ResourceLocation MJOLNIR_GLOW = loc("textures/entity/thor/mjolnir_glow.png");
   public static final String MJOLNIR_BONE = "mjolnir";

   public static final String BODY_BONE = "body";
   public static final String HEAD = "head";
   public static final String BEARD = "beard";
   public static final String BELLY = "belly";
   public static final String RIGHT_ARM = "right_arm";
   public static final String LEFT_ARM = "left_arm";
   public static final String RIGHT_FOREARM = "right_forearm";
   public static final String LEFT_FOREARM = "left_forearm";
   public static final String RIGHT_HAND = "right_hand";
   public static final String LEFT_HAND = "left_hand";
   public static final String RIGHT_LEG = "right_leg";
   public static final String LEFT_LEG = "left_leg";
   public static final String RIGHT_SHIN = "right_shin";
   public static final String LEFT_SHIN = "left_shin";
   /** Ankle bones (owner playtest: Thor stood on his toes): the boots, turned so the soles stay flat. */
   public static final String RIGHT_FOOT = "right_foot";
   public static final String LEFT_FOOT = "left_foot";
   /** Locator (no cubes) at the right fist centre: Mjölnir's grip and the right hand's IK tip. */
   public static final String MJOLNIR_GRIP = "mjolnir_grip";
   /** Locator at the left fist centre: the left hand's IK tip and a second-hand grip. */
   public static final String LEFT_GRIP = "left_grip";
   /** Locator on the body at the right hip: Mjölnir hangs here when it is on the belt. */
   public static final String MJOLNIR_BELT_BONE = "mjolnir_belt";
   /** First-person arm roots in thor_arms.geo.json (PlayerGeoLayer maps them onto the vanilla arms). */
   public static final String FP_RIGHT_ARM = "armorRightArm";
   public static final String FP_LEFT_ARM = "armorLeftArm";

   /** Every bone R2 may key, in hierarchy order (the bone contract test checks the geo against it). */
   public static final List<String> BONES = List.of(BODY_BONE, BELLY, HEAD, BEARD, RIGHT_ARM, RIGHT_FOREARM, RIGHT_HAND, MJOLNIR_GRIP,
      LEFT_ARM, LEFT_FOREARM, LEFT_HAND, LEFT_GRIP, MJOLNIR_BELT_BONE, RIGHT_LEG, RIGHT_SHIN, RIGHT_FOOT, LEFT_LEG, LEFT_SHIN, LEFT_FOOT);

   /** Clips of thor.animation.json used by R1 (R2 adds the rest). */
   public static final String CLIP_CROUCH = "crouch";
   public static final String CLIP_SIT = "sit";
   public static final String CLIP_LIFT = "lift_squat";

   private ThorAssets() {
   }

   private static ResourceLocation loc(String path) {
      return new ResourceLocation("viltrumitecore", path);
   }
}
